local CoWait = CS.Engine.Lib.CoWait
local util = require 'XLua.util'
local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule
local UIFightReardsNode = "Game.UI.FightReady.UIFightReardsNode.UIFightReardsNode"

---@class UIFightTeamRewardsNode
---@field CardPar                       	UnityEngine.RectTransform                            
local UIFightTeamRewardsNode = Class("UIFightTeamRewardsNode")
function UIFightTeamRewardsNode:__init() 
    self._curLevelId = nil
end

function UIFightTeamRewardsNode:__delete()
    self._curLevelId = nil
end

function UIFightTeamRewardsNode:Awake()
    CfUtils.FillText(self.TitleName, localize("奖励预览"))
    SetButtonAction(self.BtnReward, Bind(self, self.OnBtnRewards))
end

function UIFightTeamRewardsNode:Start()
end

function UIFightTeamRewardsNode:Refresh(data, levelId)
    if not data or table.count(data) <= 0 then
        KTool.SetActive(self.controller.gameObject, false)
        return
    end
    self._curLevelId = levelId
    local curLevelType = GoodsUtils.GetIdType(self._curLevelId, Constants.IDArea.Quests)     --关卡类型
    local isFillTitle = false
    if curLevelType == Constants.IDType.QuestCoinsCopy or curLevelType == Constants.IDType.QuestExpCopy or
     curLevelType == Constants.IDType.QuestUpStarCopy or curLevelType == Constants.IDType.QuestPrimaryEquipCopy 
     or Constants.IDType.QuestPrimaryEquipCopy or curLevelType == Constants.IDType.QuestDaily then
        isFillTitle = true
    end
    
    KTool.SetActive(self.UIFightReardsNode, true)
    local scr = CfUtils.GetLuaScr(self.UIFightReardsNode, UIFightReardsNode)
    if scr then
        scr:Refersh(data, 0.8, isFillTitle)
        scr:RefershSpacing(-40)
    end 
end

--高级装备副本的奖励显示
function UIFightTeamRewardsNode:RefreshSeniorEquipCopyInfo(data)
    if not data then
        return
    end
    CfUtils.FillText(self.TxtName, data.desc)
    CfUtils.FillText(self.TxtNum, data.num)

    KTool.SetActive(self.FastReliefReard, true)
end

--刷新标题
function UIFightTeamRewardsNode:RefreshTitle(name)
    local curLevelType = GoodsUtils.GetIdType(self._curLevelId, Constants.IDArea.Quests)     --关卡类型

    --抽卡副本特殊处理
    if self.curLevelType == Constants.IDType.QuestGachaCoin or self.curLevelType == Constants.IDType.QuestGachaCoinChallenge then
        ---@type GachaCoinQuestConstants
        local GCQConstants = import('Game.UI.FightReady.FightEnter.GachaCoinQuest.GachaCoinQuestConstants')
        ---@type GachaCoinQuestUtils
        local GCQUtils = import(GCQConstants.Path.Utils)
        local gachaCoinQuestDojo = GCQUtils.GetHomeDojo()
        local coinMax = GCQUtils.GetGachaCoinMaxByLevel(checkNumber(gachaCoinQuestDojo.copyLevel))
        local getCoin = checkNumber(gachaCoinQuestDojo.gachaCoinAmount)

        if getCoin >= coinMax then
            CfUtils.FillText(self.cfText4, localize("本周已获得奖励达到上限"))
        end
    end
end 

function UIFightTeamRewardsNode:SetBtnRewardStatu(isTrue)
    KTool.SetActive(self.BtnReward, isTrue)
end

function UIFightTeamRewardsNode:OnBtnRewards()
    if self._curLevelId then
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightBonus, parameters = { levelId = self._curLevelId } })
    end
end

function UIFightTeamRewardsNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIFightTeamRewardsNode
